import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Variable: item_table","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/bedrock-data/variables/item_table.md","filePath":"api/@jsprismarine/bedrock-data/variables/item_table.md"}`),a={name:`api/@jsprismarine/bedrock-data/variables/item_table.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/bedrock-data</a> / item_table</p><h1 id="variable-item-table" tabindex="-1">Variable: item_table <a class="header-anchor" href="#variable-item-table" aria-label="Permalink to “Variable: item_table”">​</a></h1><blockquote><p><code>const</code> <strong>item_table</strong>: <code>Record</code>&lt;<code>string</code>, <a href="./../interfaces/ItemTypeEntry.html"><code>ItemTypeEntry</code></a>&gt; = <code>item_table_data</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/bedrock-data/src/index.ts#L47" target="_blank" rel="noreferrer">index.ts:47</a></p><p>The item table: every name the client can be told about, and the number it travels as.</p><p>The authority on the mapping - the client builds its registry from what we send, so everything naming an item has to agree with this one file.</p><p>Captured from a Bedrock Dedicated Server 1.26.51.1, not taken from a third party: the server sends it as <code>ItemRegistryPacket</code>, so a client that can log in can simply record it. <code>packages/client/tools/capture-server-data.mjs</code> is that client, and its output is <code>jsp/required_item_list.json</code>. It stays under <code>jsp/</code> rather than moving to <code>resources/</code> because a capture of the version this server targets is the thing nothing else can promise.</p><p>The capture records no <code>version</code>. <code>utils/build.js</code> takes that one column from the submodule&#39;s <code>runtime_item_states.json</code>, a dump of 1.26.50 at the same protocol, and refuses to generate the table unless the two agree on every name, id and component flag. They do.</p><p>The version matters more than it looks. Against the 1.21.40 table this has 240 names it did not, and - the part that breaks quietly - <strong>528 items whose number changed</strong>. A server on the old table does not fail; it puts the wrong number on the wire for a quarter of the items it knows, and the client shows something else.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};